begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
create temp table practice_test_results(line text);
create temp table practice_data(name text primary key,value jsonb);
grant all on practice_test_results,practice_data to authenticated,anon,service_role;
grant usage on schema extensions to authenticated,anon,service_role;
set local role anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role service_role;
reset role;
set local role service_role;
do $$ begin for i in 1..20 loop perform public.practice_guest('create',repeat('d',64),repeat('e',64),null,null,gen_random_uuid()); end loop; end $$;
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='f2000000-0000-4000-8000-000000000001';
set local role authenticated;
reset role;
select line from practice_test_results;
rollback;
